import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'
import Lightbox from 'yet-another-react-lightbox'
import Zoom from 'yet-another-react-lightbox/plugins/zoom'
import Fullscreen from 'yet-another-react-lightbox/plugins/fullscreen'
import 'yet-another-react-lightbox/styles.css'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"

interface ImageSharpEdge {
  node: {
    publicURL: string
    childImageSharp: {
      thumb: IGatsbyImageData
      full: IGatsbyImageData
    }
  }
}

interface PageProps {
  data: {
    images: {
      edges: ImageSharpEdge[]
    }
  }
}

const ArtGalleryTemplate: React.FC<PageProps> = ({ data }) => {
  const [lightboxIndex, setLightboxIndex] = React.useState(-1)

  // Shuffle images for random display order
  const shuffledEdges = React.useMemo(() => {
    const edges = [...data.images.edges]
    for (let i = edges.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[edges[i], edges[j]] = [edges[j], edges[i]]
    }
    return edges
  }, [data.images.edges])

  // Transform images for lightbox
  const lightboxSlides = shuffledEdges.map(({ node }) => {
    return {
      src: node.publicURL,
    }
  })

  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <Link to="/creations" className="back-link">
          ← Back to Creations
        </Link>
        <h1>Art</h1>
        <p>A collection of early drawings, paintings, and digital work that started my creative journey.</p>
        <div className="accent-line"></div>
      </div>
      <div className="masonry-gallery">
        {shuffledEdges.map(({ node }, index) => {
          const image = getImage(node.childImageSharp.thumb)
          if (!image) return null

          return (
            <div
              key={index}
              className="gallery-item"
              onClick={() => setLightboxIndex(index)}
            >
              <GatsbyImage
                image={image}
                alt={`Art - Image ${index + 1}`}
                className="gallery-thumb"
              />
            </div>
          )
        })}
      </div>
      <div className="back-to-top-container">
        <button
          className="back-to-top"
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
        >
          ↑ Back to Top
        </button>
      </div>
      <Lightbox
        open={lightboxIndex >= 0}
        close={() => setLightboxIndex(-1)}
        index={lightboxIndex}
        slides={lightboxSlides}
        plugins={[Zoom, Fullscreen]}
        zoom={{
          maxZoomPixelRatio: 3,
          scrollToZoom: true,
        }}
        carousel={{
          finite: false,
          spacing: 0,
          padding: 0
        }}
        animation={{
          fade: 250,
          swipe: 500,
          navigation: 500,
          easing: {
            fade: "ease-out",
            swipe: "ease-in-out",
            navigation: "ease-in-out"
          }
        }}
      />
      <Footer />
    </div>
  )
}

export const query = graphql`
  query ArtGalleryTemplateQuery {
    images: allFile(
      filter: { sourceInstanceName: { eq: "art" } }
      sort: { name: ASC }
    ) {
      edges {
        node {
          publicURL
          childImageSharp {
            thumb: gatsbyImageData(
              width: 800
              placeholder: BLURRED
            )
            full: gatsbyImageData(layout: FULL_WIDTH)
          }
        }
      }
    }
  }
`

export default ArtGalleryTemplate
